import re,html,json,hashlib,shutil,subprocess,pathlib,importlib.util
p='products/services/diversified-offers/raw/forhire-hiring.rss'
b=open(p,'rb').read()
t=b.decode('utf-8')
entries=re.findall(r'<entry>(.*?)</entry>',t,re.S)
post=None
for e in entries:
  if '1xp9pdj' in e: post=e
out={'rss_sha256':hashlib.sha256(b).hexdigest(),'entries':len(entries)}
if post:
  c=re.search(r'<content[^>]*>(.*?)</content>',post,re.S)
  body=html.unescape(c.group(1)) if c else ''
  body=html.unescape(re.sub(r'<[^>]+>',' ',body))
  out['post_text']=re.sub(r'\s+',' ',body).strip()
  for tag in ['updated','published','title']:
    m=re.search(r'<%s[^>]*>(.*?)</%s>'%(tag,tag),post,re.S); out[tag]=html.unescape(m.group(1)) if m else None
  out['author']=re.findall(r'<name>(.*?)</name>',post)
tools={}
for x in ['node','tidy','xmllint','chromium','chromium-browser','google-chrome','firefox','lighthouse','npx','html5validator','java','vnu','stylelint','csslint','eslint','prettier']:
  tools[x]=shutil.which(x)
mods={m:bool(importlib.util.find_spec(m)) for m in ['html5lib','bs4','lxml','tinycss2','cssutils','playwright','selenium','html.parser']}
out['tools']=tools; out['python_modules']=mods
try: out['node_version']=subprocess.run(['node','--version'],capture_output=True,text=True).stdout.strip()
except Exception as ex: out['node_version']=repr(ex)
nm=subprocess.run(['node','-e','const r=[];for(const m of ["jsdom","parse5","acorn","csstree","css-tree","puppeteer","playwright","htmlhint"]){try{require.resolve(m);r.push(m+":yes")}catch(e){r.push(m+":no")}};console.log(r.join(","))'],capture_output=True,text=True)
out['node_modules']=nm.stdout.strip()
out['node_check_flag']=subprocess.run(['node','--check','/dev/null'],capture_output=True,text=True).returncode
d=pathlib.Path('products/services/diversified-offers/website-verification');d.mkdir(parents=True,exist_ok=True)
(d/'capability-and-source-check.json').write_text(json.dumps(out,indent=1,ensure_ascii=False))
print(json.dumps(out,indent=1,ensure_ascii=False)[:6000])
